                continue
            col = g[r][c]
            q = [(r,c)]
            seen.add((r,c))
            cells = []
            while q:
                x,y = q.pop()
                cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx,ny) not in seen and g[nx][ny] == col:
                        seen.add((nx,ny)); q.append((nx,ny))
            rs = [x for x,y in cells]; cs = [y for x,y in cells]
            comps.append({'color':col, 'cells':cells, 'box':(min(rs),min(cs),max(rs),max(cs)), 'sig':_canon(cells)})
