        edges = set()
        for r,c in o['cells']:
            if r == 0: edges.add('T')
            if r == h-1: edges.add('B')
            if c == 0: edges.add('L')
            if c == w-1: edges.add('R')
        if ('T' in edges and 'L' in edges) or ('T' in edges and 'R' in edges) or ('B' in edges and 'L' in edges) or ('B' in edges and 'R' in edges):
